import{services as originalServices}from'./content.js?v=95d153d545';
import{services as design42Services}from'./services-04-2.js?v=95d153d545';
import{initExpandingSearch}from'./expanding-search.js?v=95d153d545';
import{initFaqSection}from'./faq-section.js?v=95d153d545';
import{initFrostNav}from'./frost-nav.js?v=95d153d545';
const services=['04.2','04.5'].includes(document.documentElement.dataset.design)?design42Services:originalServices;
// Set by build.mjs on 04.5 only: the patient portal's base URL (PORTAL_URL).
const portal=document.documentElement.dataset.portal;
const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
if(document.documentElement.dataset.design==='04.2')initFrostNav(document.querySelector('.topbar'));
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
if(!reduced){document.body.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(isIntersecting){target.classList.add('in-view');observer.unobserve(target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
const toggle=document.querySelector('.menu-toggle'),panel=document.querySelector('.menu-panel'),backdrop=document.querySelector('.menu-backdrop');
function closeMenu(restore=false){toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open menu');panel.hidden=true;backdrop.hidden=true;if(restore)toggle.focus()}
function openMenu(){toggle.setAttribute('aria-expanded','true');toggle.setAttribute('aria-label','Close menu');panel.hidden=false;backdrop.hidden=false}
toggle.setAttribute('aria-label','Open menu');toggle.addEventListener('click',()=>panel.hidden?openMenu():closeMenu());backdrop.addEventListener('click',()=>closeMenu(true));panel.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{closeMenu();const el=document.querySelector(a.hash);if(el){el.setAttribute('tabindex','-1');el.focus({preventScroll:true})}}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)closeMenu(true)});
// Gentle photographic drift and layered sticky cards, driven by scroll position.
if(!reduced){const hero=document.querySelector('.hero'),photo=document.querySelector('.hero-photo'),cards=[...document.querySelectorAll('.treatment-card,.visit-card')];let pending=false;function paint(){pending=false;const y=scrollY;if(y<hero.offsetHeight&&!photo.closest('[data-glass]'))photo.style.translate=`0 ${y*.12}px`;cards.forEach(card=>{const r=card.getBoundingClientRect(),next=card.nextElementSibling;if(!next)return;const n=next.getBoundingClientRect(),progress=Math.max(0,Math.min(1,(r.bottom-n.top+80)/Math.max(1,r.height)));card.style.transform=`scale(${1-progress*.035})`;card.style.filter=`brightness(${1-progress*.12})`})}function request(){if(!pending){pending=true;requestAnimationFrame(paint)}}addEventListener('scroll',request,{passive:true});addEventListener('resize',request,{passive:true});paint()}
const dialog=document.querySelector('#care-dialog'),content=document.querySelector('#dialog-content');let opener;
function show(html,trigger){opener=trigger;content.innerHTML=html;closeMenu();dialog.showModal();document.body.style.overflow='hidden';dialog.scrollTop=0;dialog.querySelector('.dialog-close').focus()}
function showService(id,trigger){const s=services.find(s=>s.id===id);if(!s)return;show(`<p class="mono">Care that fits your life</p><h2 id="dialog-title">${esc(s.name)}</h2><p>${esc(s.description)}</p><div class="dialog-price"><strong>From €${s.price}</strong><span>${s.duration} · video consultation</span></div><ul class="dialog-list">${s.topics.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="dialog-note">Example prices are confirmed per country before launch. Prescriptions, certificates, referrals, and tests depend on your clinician’s assessment. Not an emergency service. In an emergency, call 112.</p>${portal?`<a class="button dark" href="${esc(portal)}/book?service=${encodeURIComponent(s.id)}">Book ${esc(s.name)}</a>`:'<a class="button dark" href="https://carevia.triple-labs-8416.chatgpt.site/#services" target="_blank" rel="noopener">Explore on Carevia</a>'}`,trigger)}
const searchRoot=document.querySelector('[data-care-search]');
if(searchRoot)initExpandingSearch(searchRoot,services,(service,trigger)=>showService(service.id,trigger),()=>closeMenu());
const faqRoot=document.querySelector('[data-faq-section]');
if(faqRoot)initFaqSection(faqRoot);
document.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>showService(b.dataset.service,b)));document.querySelector('[data-all-care]').addEventListener('click',e=>{show(`<p class="mono">Seven areas of care</p><h2 id="dialog-title">Find your starting point.</h2><p>Choose an area to explore the consultation, example price, and next steps.</p><div class="all-care-list">${services.map(s=>`<button data-service="${s.id}">${esc(s.name)}<span>From €${s.price}</span></button>`).join('')}</div>`,e.currentTarget);content.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>showService(b.dataset.service,opener)))});dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus({preventScroll:true})});
document.querySelectorAll('.faq-toggle').forEach(b=>b.addEventListener('click',()=>{const item=b.closest('.faq-item'),open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!open));item.classList.toggle('open',!open);item.querySelector('.faq-answer').inert=open}));
const statements={heard:['Good care starts with being heard. A little more understanding. A little more clarity. More room to be you.','A conversation with space for your questions, your concerns, and what matters most to you.'],clear:['A real conversation. A clear price. A next step you understand. Care should feel more straightforward.','See the consultation price before confirming. Pay for the visit you choose, with no subscription.'],together:['The conversation is just the beginning. Keep the details together, and your next step close.','Your clinical summary, and anything your doctor decides to issue, is available through iMED, Carevia’s clinical system.']};document.querySelectorAll('[data-principle]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-principle]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b))});const [heading,copy]=statements[b.dataset.principle],h=document.querySelector('.approach-statement');h.textContent=heading;document.querySelector('.principle-copy').textContent=copy;if(!reduced)h.animate([{opacity:0,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:450,easing:'ease-out'})}));
import{GlassPhoto}from'./glass.js?v=95d153d545';document.querySelectorAll('.hero [data-glass],.wide-banner [data-glass],.treatment-card [data-glass],.start-card [data-glass]').forEach(el=>new GlassPhoto(el,reduced));

// Load the Paper heatmap only when its card nears the viewport; the static logo stays if WebGL is unavailable.
const heatmap=document.querySelector('[data-heatmap]');
if(heatmap&&'IntersectionObserver'in window)new IntersectionObserver(([entry],observer)=>{if(!entry.isIntersecting)return;observer.disconnect();import('./start-heatmap.js?v=95d153d545').then(m=>m.mountHeatmap(heatmap)).catch(()=>{})},{rootMargin:'400px'}).observe(heatmap);
